indirect enum Value {
    case integer(Int), boolean(Bool), string(String), pair(Value, Value), list([Value]), closure(Closure), builtin(String)
}
typealias ValueEnvironment = [String: Value]
final class EnvironmentBox {
    var values: ValueEnvironment;
    init(_ values: ValueEnvironment) {
        self.values = values
    }
}
struct Closure {
    let parameter: Parameter, body: Expr, environment: EnvironmentBox
}
struct RuntimeError: Error {
    let position: Position, message: String
}
func checkedInteger(_ value: Int, _ position: Position) throws -> Value {
    guard (-2147483648...2147483647).contains(value) else {
        throw RuntimeError(position: position, message: "integer overflow")
    };
    return .integer(value)
}
func compareValues(_ a: Value, _ b: Value, _ position: Position) throws -> Int {
    switch (a, b) {
        case (.integer(let a), .integer(let b)): return a < b ? -1 : a > b ? 1 : 0
        case (.boolean(let a), .boolean(let b)): return a == b ? 0 : a ? 1 : -1
        case (.string(let a), .string(let b)): return a < b ? -1 : a > b ? 1 : 0
        case (.pair(let a, let b), .pair(let c, let d)): let first = try compareValues(a, c, position);
        return first == 0 ? try compareValues(b, d, position) : first
        case (.list(let a), .list(let b)):
        for (a, b) in zip(a, b) {
            let order = try compareValues(a, b, position);
            if order != 0 {
                return order
            }
        };
        return a.count < b.count ? -1 : a.count > b.count ? 1 : 0
        default: throw RuntimeError(position: position, message: "functional value compared")
    }
}
func matchPattern(_ pattern: Pattern, _ value: Value, _ bindings: inout ValueEnvironment) -> Bool {
    switch (pattern.kind, value) {
        case (.wildcard, _): return true
        case (.name(let name), _): bindings[name] = value;
        return true
        case (.integer(let a), .integer(let b)): return a == b
        case (.boolean(let a), .boolean(let b)): return a == b
        case (.string(let a), .string(let b)): return a == b
        case (.nilList, .list(let values)): return values.isEmpty
        case (.cons(let a, let b), .list(let values)): return !values.isEmpty && matchPattern(a, values[0], &bindings) && matchPattern(b, .list(Array(values.dropFirst())), &bindings)
        case (.list(let patterns), .list(let values)):
        if patterns.count != values.count {
            return false
        };
        for (p, v) in zip(patterns, values) {
            if !matchPattern(p, v, &bindings) {
                return false
            }
        };
        return true
        case (.pair(let a, let b), .pair(let c, let d)): return matchPattern(a, c, &bindings) && matchPattern(b, d, &bindings)
        default: return false
    }
}
final class Evaluator {
    var calls = 0
    func group(_ group: Group, _ environment: ValueEnvironment) throws -> (ValueEnvironment, [Value]) {
        var values: [Value] = []
        if group.recursive != nil {
            let shared = EnvironmentBox(environment)
            for binding in group.bindings {
                if case .fun(let parameter, let body) = binding.expression.kind {
                    values.append(.closure(Closure(parameter: parameter, body: body, environment: shared)))
                }
            }
            for (binding, value) in zip(group.bindings, values) {
                shared.values[binding.name] = value
            };
            return (shared.values, values)
        }
        for binding in group.bindings {
            values.append(try expression(binding.expression, environment))
        }
        var result = environment;
        for (binding, value) in zip(group.bindings, values) {
            result[binding.name] = value
        };
        return (result, values)
    }
    func apply(_ function: Value, _ argument: Value, _ position: Position) throws -> Value {
        calls += 1
        switch function {
            case .closure(let closure): var environment = closure.environment.values;
            if let name = closure.parameter.name {
                environment[name] = argument
            };
            return try expression(closure.body, environment)
            case .builtin(let name): return try applyBuiltin(name, argument, position)
            default: preconditionFailure()
        }
    }
    func expression(_ expression: Expr, _ environment: ValueEnvironment) throws -> Value {
        switch expression.kind {
            case .integer(let value): return .integer(value)
            case .boolean(let value): return .boolean(value)
            case .string(let value): return .string(value)
            case .name(let name): return environment[name]!
            case .fun(let parameter, let body): return .closure(Closure(parameter: parameter, body: body, environment: EnvironmentBox(environment)))
            case .apply(let function, let argument): let f = try self.expression(function, environment), a = try self.expression(argument, environment);
            return try apply(f, a, expression.position)
            case .negate(let position, let value): guard case .integer(let number) = try self.expression(value, environment) else {
                preconditionFailure()
            };
            return try checkedInteger(-number, position)
            case .binary(let op, let position, let a, let b):
            let left = try self.expression(a, environment)
            if op == "&&", case .boolean(let flag) = left {
                return flag ? try self.expression(b, environment) : .boolean(false)
            }
            if op == "||", case .boolean(let flag) = left {
                return flag ? .boolean(true) : try self.expression(b, environment)
            }
            let right = try self.expression(b, environment)
            switch op {
                case "+", "-", "*", "/", "mod":
                guard case .integer(let a) = left, case .integer(let b) = right else {
                    preconditionFailure()
                }
                if (op == "/" || op == "mod") && b == 0 {
                    throw RuntimeError(position: position, message: "division by zero")
                }
                let value: Int;
                switch op {
                    case "+": value = a + b;
                    case "-": value = a - b;
                    case "*": value = a * b;
                    case "/": value = a / b;
                    default: value = a - b * (a / b)
                };
                return try checkedInteger(value, position)
                case "^": guard case .string(let a) = left, case .string(let b) = right else {
                    preconditionFailure()
                };
                return .string(a + b)
                case "::": guard case .list(let values) = right else {
                    preconditionFailure()
                };
                return .list([left] + values)
                default: let order = try compareValues(left, right, position);
                let value: Bool;
                switch op {
                    case "=": value = order == 0;
                    case "<>": value = order != 0;
                    case "<": value = order < 0;
                    case ">": value = order > 0;
                    case "<=": value = order <= 0;
                    default: value = order >= 0
                };
                return .boolean(value)
            }
            case .conditional(let condition, let yes, let no): guard case .boolean(let flag) = try self.expression(condition, environment) else {
                preconditionFailure()
            };
            return try self.expression(flag ? yes : no, environment)
            case .pair(let a, let b): let first = try self.expression(a, environment), second = try self.expression(b, environment);
            return .pair(first, second)
            case .list(let elements): var values: [Value] = [];
            for element in elements {
                values.append(try self.expression(element, environment))
            };
            return .list(values)
            case .match(let value, let arms):
            let matched = try self.expression(value, environment)
            for (pattern, body) in arms {
                var bindings: ValueEnvironment = [:];
                if matchPattern(pattern, matched, &bindings) {
                    return try self.expression(body, environment.merging(bindings) {
                        _, new in new
                    })
                }
            }
            throw RuntimeError(position: expression.position, message: "match failure")
            case .letIn(let group, let body): let (inner, _) = try self.group(group, environment);
            return try self.expression(body, inner)
        }
    }
}

enum TypeErrorKind {
    case message(String), function(MLType), check(MLType, MLType, UnifyFailure)
}
struct TypeError: Error {
    let position: Position, kind: TypeErrorKind
}
struct Local {
    let name: String, position: Position, scheme: Scheme
}
final class Inference {
    let unifier = Unifier();
    var locals: [Local] = [], matches: [Position: (MLType, [Pattern])] = [:]
    func clear() {
        locals = [];
        matches = [:]
    }
    func message(_ position: Position, _ message: String) -> TypeError {
        TypeError(position: position, kind: .message(message))
    }
    func check(_ expected: MLType, _ found: MLType, _ position: Position) throws {
        do {
            try unifier.unify(expected, found)
        } catch let failure as UnifyFailure {
            throw TypeError(position: position, kind: .check(expected, found, failure))
        }
    }
    func group(_ group: Group, _ environment: TypeEnvironment, _ local: Bool) throws -> (TypeEnvironment, [Scheme]) {
        var names: Set<String> = []
        for binding in group.bindings {
            if !names.insert(binding.name).inserted {
                throw message(binding.position, "variable '\(binding.name)' is bound twice in this let")
            }
            if group.recursive != nil {
                guard case .fun = binding.expression.kind else {
                    throw message(binding.position, "'\(binding.name)' in let rec must be a function")
                }
            }
        }
        var recursive = environment, types: [MLType] = []
        if group.recursive != nil {
            for binding in group.bindings {
                let type = unifier.fresh();
                recursive[binding.name] = .mono(type);
                types.append(type)
            }
            for (i, binding) in group.bindings.enumerated() {
                let found = try expression(binding.expression, recursive);
                try check(types[i], found, binding.position)
            }
        } else {
            for binding in group.bindings {
                types.append(try expression(binding.expression, environment))
            }
        }
        let schemes = types.map {
            unifier.generalize($0, environment)
        };
        var result = environment
        for (binding, scheme) in zip(group.bindings, schemes) {
            result[binding.name] = scheme;
            if local {
                locals.append(Local(name: binding.name, position: binding.position, scheme: scheme))
            }
        };
        return (result, schemes)
    }
    func expression(_ expression: Expr, _ environment: TypeEnvironment) throws -> MLType {
        switch expression.kind {
            case .integer: return .integer
            case .boolean: return .boolean
            case .string: return .string
            case .name(let name):
            if let scheme = environment[name] {
                return unifier.instantiate(scheme)
            }
            let candidate = environment.keys.map {
                (editDistance(name, $0), $0)
            }.filter {
                $0.0 <= 2 && $0.0 < name.count
            }.min {
                $0 < $1
            }
            throw message(expression.position, "unbound variable '\(name)'" + (candidate.map {
                " (did you mean '\($0.1)'?)"
            } ?? ""))
            case .fun(let parameter, let body):
            let argument = unifier.fresh();
            var inner = environment;
            if let name = parameter.name {
                inner[name] = .mono(argument)
            };
            let result = try self.expression(body, inner);
            return .function(argument, result)
            case .apply(let function, let argument):
            let functionType = try self.expression(function, environment), expected: MLType, result: MLType
            switch unifier.resolve(functionType) {
                case .variable(let i): expected = unifier.fresh();
                result = unifier.fresh();
                unifier.bind(i, .function(expected, result))
                case .function(let a, let b): expected = a;
                result = b
                case let type: throw TypeError(position: function.position, kind: .function(type))
            }
            let found = try self.expression(argument, environment);
            try check(expected, found, argument.position);
            return result
            case .binary(let op, _, let left, let right):
            let a: MLType, b: MLType, result: MLType
            switch op {
                case "+", "-", "*", "/", "mod": a = .integer;
                b = .integer;
                result = .integer
                case "^": a = .string;
                b = .string;
                result = .string
                case "&&", "||": a = .boolean;
                b = .boolean;
                result = .boolean
                case "::": a = unifier.fresh();
                b = .list(a);
                result = .list(a)
                default: a = unifier.fresh();
                b = a;
                result = .boolean
            }
            let first = try self.expression(left, environment);
            try check(a, first, left.position);
            let second = try self.expression(right, environment);
            try check(b, second, right.position);
            return result
            case .negate(_, let value): let found = try self.expression(value, environment);
            try check(.integer, found, value.position);
            return .integer
            case .conditional(let condition, let yes, let no):
            let found = try self.expression(condition, environment);
            try check(.boolean, found, condition.position);
            let a = try self.expression(yes, environment), b = try self.expression(no, environment);
            try check(a, b, no.position);
            return a
            case .pair(let a, let b): let first = try self.expression(a, environment), second = try self.expression(b, environment);
            return .pair(first, second)
            case .list(let elements): let type = unifier.fresh();
            for value in elements {
                let found = try self.expression(value, environment);
                try check(type, found, value.position)
            };
            return .list(type)
            case .match(let value, let arms):
            let type = try self.expression(value, environment), result = unifier.fresh()
            for (pattern, body) in arms {
                var bindings: [String: MLType] = [:];
                let found = try self.pattern(pattern, &bindings);
                try check(type, found, pattern.position)
                var inner = environment;
                for (name, type) in bindings {
                    inner[name] = .mono(type)
                };
                let bodyType = try self.expression(body, inner);
                try check(result, bodyType, body.position)
            }
            matches[expression.position] = (type, arms.map {
                $0.0
            });
            return result
            case .letIn(let group, let body): let (inner, _) = try self.group(group, environment, true);
            return try self.expression(body, inner)
        }
    }
    func pattern(_ pattern: Pattern, _ bindings: inout [String: MLType]) throws -> MLType {
        switch pattern.kind {
            case .wildcard: return unifier.fresh()
            case .name(let name): if bindings[name] != nil {
                throw message(pattern.position, "variable '\(name)' is bound twice in this pattern")
            };
            let type = unifier.fresh();
            bindings[name] = type;
            return type
            case .integer: return .integer
            case .boolean: return .boolean
            case .string: return .string
            case .nilList: return .list(unifier.fresh())
            case .cons(let a, let b): let type = unifier.fresh(), head = try self.pattern(a, &bindings);
            try check(type, head, a.position);
            let tail = try self.pattern(b, &bindings), list = MLType.list(type);
            try check(list, tail, b.position);
            return list
            case .list(let elements): let type = unifier.fresh();
            for value in elements {
                let found = try self.pattern(value, &bindings);
                try check(type, found, value.position)
            };
            return .list(type)
            case .pair(let a, let b): let first = try self.pattern(a, &bindings), second = try self.pattern(b, &bindings);
            return .pair(first, second)
        }
    }
}

struct Position: Hashable, Comparable {
    let file: Int, line: Int, column: Int
    static func < (a: Self, b: Self) -> Bool {
        (a.file, a.line, a.column) < (b.file, b.line, b.column)
    }
}
struct Token: Error {
    let kind: String, spelling: String, value: String, position: Position
}
enum Lexer {
    static func lex(_ text: String, _ file: Int) -> [Token] {
        let bytes = Array(text.utf8)
        var positions: [Position] = [], row = 1, column = 1
        for c in bytes {
            positions.append(Position(file: file, line: row, column: column));
            if c == 10 {
                row += 1;
                column = 1
            } else {
                column += 1
            }
        }
        positions.append(Position(file: file, line: row, column: column))
        func digit(_ c: UInt8) -> Bool {
            (48...57).contains(c)
        }
        func letter(_ c: UInt8) -> Bool {
            (65...90).contains(c) || (97...122).contains(c)
        }
        func word(_ a: Int, _ b: Int) -> String {
            String(decoding: bytes[a..<b], as: UTF8.self)
        }
        var tokens: [Token] = [], i = 0
        while i < bytes.count {
            if bytes[i] == 32 || bytes[i] == 10 {
                i += 1;
                continue
            }
            let start = i
            var kind = "", value = ""
            if i + 1 < bytes.count && word(i, i + 2) == "(*" {
                i += 2
                while i + 1 < bytes.count && word(i, i + 2) != "*)" {
                    i += 1
                }
                if i + 1 < bytes.count {
                    i += 2;
                    continue
                }
                tokens.append(Token(kind: "invalid", spelling: word(start, bytes.count), value: "unterminated comment", position: positions[start]));
                break
            } else if digit(bytes[i]) {
                i += 1;
                while i < bytes.count && digit(bytes[i]) {
                    i += 1
                }
                if let n = Int(word(start, i)), n <= 2147483647 {
                    kind = "integer";
                    value = String(n)
                } else {
                    kind = "invalid";
                    value = "integer literal too large"
                }
            } else if letter(bytes[i]) || bytes[i] == 95 {
                i += 1;
                while i < bytes.count && (letter(bytes[i]) || digit(bytes[i]) || bytes[i] == 95 || bytes[i] == 39) {
                    i += 1
                }
                value = word(start, i);
                kind = ["let", "rec", "and", "in", "fun", "if", "then", "else", "match", "with", "true", "false", "mod", "val"].contains(value) ? "keyword" : "identifier"
            } else if bytes[i] == 39 && i + 1 < bytes.count && (97...122).contains(bytes[i + 1]) {
                i += 2;
                while i < bytes.count && (letter(bytes[i]) || digit(bytes[i]) || bytes[i] == 95) {
                    i += 1
                }
                kind = "type_variable";
                value = word(start, i)
            } else if bytes[i] == 34 {
                i += 1;
                var closed = false, valid = true, decoded: [UInt8] = []
                while i < bytes.count && bytes[i] != 10 {
                    if bytes[i] == 34 {
                        i += 1;
                        closed = true;
                        break
                    }
                    if bytes[i] == 92 && i + 1 < bytes.count && bytes[i + 1] != 10 {
                        switch bytes[i + 1] {
                            case 110: decoded.append(10);
                            case 116: decoded.append(9);
                            case 92: decoded.append(92);
                            case 34: decoded.append(34);
                            default: valid = false
                        };
                        i += 2
                    } else if bytes[i] == 92 {
                        i += 1
                    }
                    else {
                        decoded.append(bytes[i]);
                        i += 1
                    }
                }
                if !closed {
                    kind = "invalid";
                    value = "unterminated string"
                } else if !valid {
                    kind = "invalid";
                    value = "invalid escape sequence"
                } else {
                    kind = "string";
                    value = String(decoding: decoded, as: UTF8.self)
                }
            } else {
                kind = "symbol"
                if i + 1 < bytes.count && [";;", "->", "::", "||", "&&", "<=", ">=", "<>"].contains(word(i, i + 2)) {
                    i += 2
                }
                else if Array(":;=<>+-*/^()[],|".utf8).contains(bytes[i]) {
                    i += 1
                }
                else {
                    kind = "invalid";
                    value = "illegal character '\(word(i, i + 1))'";
                    i += 1
                }
                if kind == "symbol" {
                    value = word(start, i)
                }
            }
            tokens.append(Token(kind: kind, spelling: word(start, i), value: value, position: positions[start]))
        }
        tokens.append(Token(kind: "eof", spelling: "", value: "", position: positions[bytes.count]));
        return tokens
    }
}

import Foundation
func quote(_ value: String) -> String {
    var out = "\""
    for c in value {
        switch c {
            case "\\": out += "\\\\";
            case "\"": out += "\\\"";
            case "\n": out += "\\n";
            case "\t": out += "\\t";
            default: out.append(c)
        }
    };
    return out + "\""
}
func valueString(_ value: Value) -> String {
    switch value {
        case .integer(let v): return String(v);
        case .boolean(let v): return String(v);
        case .string(let v): return quote(v);
        case .pair(let a, let b): return "(\(valueString(a)), \(valueString(b)))";
        case .list(let values): return "[" + values.map(valueString).joined(separator: "; ") + "]";
        default: return "<fun>"
    }
}
func editDistance(_ a: String, _ b: String) -> Int {
    let aa = Array(a.utf8), bb = Array(b.utf8);
    var row = Array(0...bb.count)
    for (i, a) in aa.enumerated() {
        var next = [i + 1];
        for (j, b) in bb.enumerated() {
            next.append(min(next[j] + 1, row[j + 1] + 1, row[j] + (a == b ? 0 : 1)))
        };
        row = next
    };
    return row[bb.count]
}
final class TypePrinter {
    let unifier: Unifier, quantified: Set<Int>?;
    var names: [Int: String] = [:]
    init(_ unifier: Unifier, _ quantified: Set<Int>? = nil) {
        self.unifier = unifier;
        self.quantified = quantified
    }
    func write(_ type: MLType) -> String {
        switch unifier.resolve(type) {
            case .integer: return "int"
            case .boolean: return "bool"
            case .string: return "string"
            case .variable(let i):
            if let name = names[i] {
                return name
            };
            let k = names.count, weak = quantified.map {
                !$0.contains(i)
            } ?? false
            let name = "'" + (weak ? "_" : "") + String(UnicodeScalar(97 + k % 26)!) + (k >= 26 ? String(k / 26) : "");
            names[i] = name;
            return name
            case .list(let element): return wrap(element, pair: true) + " list"
            case .pair(let a, let b): return wrap(a, pair: true) + " * " + wrap(b, pair: true)
            case .function(let a, let b): return wrap(a, pair: false) + " -> " + write(b)
        }
    }
    func wrap(_ type: MLType, pair: Bool) -> String {
        let resolved = unifier.resolve(type), text = write(resolved)
        switch resolved {
            case .function: return "(" + text + ")";
            case .pair where pair: return "(" + text + ")";
            default: return text
        }
    }
}
func errorMessage(_ error: TypeError, _ unifier: Unifier) -> String {
    let printer = TypePrinter(unifier)
    switch error.kind {
        case .message(let message): return message
        case .function(let type): return "expected a function but found \(printer.write(type))"
        case .check(let expected, let found, let failure):
        var message = "expected \(printer.write(expected)) but found \(printer.write(found))"
        if failure.occurs {
            let variable: MLType, other: MLType;
            if case .variable = failure.expected {
                variable = failure.expected;
                other = failure.found
            } else {
                variable = failure.found;
                other = failure.expected
            };
            message += " (infinite type \(printer.write(variable)) = \(printer.write(other)))"
        }
        else if failure.nested {
            message += " (\(printer.write(failure.expected)) vs \(printer.write(failure.found)))"
        };
        return message
    }
}
func signatureType(_ expression: TypeExpression, _ unifier: Unifier, _ variables: inout [String: MLType]) -> MLType {
    switch expression {
        case .primitive(let name): return name == "int" ? .integer : name == "bool" ? .boolean : .string
        case .variable(let name): if let type = variables[name] {
            return type
        };
        let type = unifier.fresh();
        variables[name] = type;
        return type
        case .list(let type): return .list(signatureType(type, unifier, &variables))
        case .pair(let a, let b): let first = signatureType(a, unifier, &variables), second = signatureType(b, unifier, &variables);
        return .pair(first, second)
        case .function(let a, let b): let first = signatureType(a, unifier, &variables), second = signatureType(b, unifier, &variables);
        return .function(first, second)
    }
}
func signatureMatches(_ inferred: MLType, _ declared: MLType, _ unifier: Unifier, _ assigned: inout [Int: MLType]) -> Bool {
    let a = unifier.resolve(inferred), b = unifier.resolve(declared)
    switch (a, b) {
        case (.variable(let i), _): if let old = assigned[i] {
            return old == b
        };
        assigned[i] = b;
        return true
        case (.list(let a), .list(let b)): return signatureMatches(a, b, unifier, &assigned)
        case (.pair(let a, let b), .pair(let c, let d)), (.function(let a, let b), .function(let c, let d)): return signatureMatches(a, c, unifier, &assigned) && signatureMatches(b, d, unifier, &assigned)
        default: return a == b
    }
}
func typeSyntax(_ type: TypeExpression) -> String {
    func wrap(_ t: TypeExpression, _ pair: Bool) -> String {
        let text = typeSyntax(t);
        switch t {
            case .function: return "(" + text + ")";
            case .pair where pair: return "(" + text + ")";
            default: return text
        }
    }
    switch type {
        case .primitive(let name), .variable(let name): return name;
        case .list(let t): return wrap(t, true) + " list";
